/**
 * Batch 6 — ~110 verified India Quiz questions.
 * 10 per category × 11 categories.
 */
import { db } from '@/lib/db';
import { checkDuplicate } from '@/lib/quiz/duplicate-detector';

interface Q {
  slug: string; categoryId: string; text: string;
  options: [string, string, string, string]; correctIndex: number;
  explanation: string; source: string; difficulty: 'easy'|'medium'|'hard';
}

const BATCH: Q[] = [
  // ═══ cat-gk (10) ═══
  { slug: 'gk-india-largest-bank-private', categoryId: 'cat-gk', text: 'Which is the largest private sector bank in India by total assets (as of 2024)?', options: ['ICICI Bank', 'HDFC Bank', 'Axis Bank', 'Kotak Mahindra Bank'], correctIndex: 1, explanation: 'HDFC Bank is the largest private sector bank in India by total assets. Following the merger of HDFC Ltd with HDFC Bank in July 2022, it became one of the world\'s top 10 banks by market capitalisation. SBI remains the largest bank overall (public sector).', source: 'Reserve Bank of India / HDFC Bank Annual Report 2023-24', difficulty: 'easy' },
  { slug: 'gk-india-railway-zone-count', categoryId: 'cat-gk', text: 'As of 2024, Indian Railways operates how many zones?', options: ['9', '14', '18', '22'], correctIndex: 2, explanation: 'As of 2024, Indian Railways operates 18 zones. The newest zone is the South Coast Railway (established in 2019, headquartered at Visakhapatnam). Indian Railways is the fourth largest railway network in the world by route length (~68,000 km) and the largest employer in India.', source: 'Indian Railways / Ministry of Railways', difficulty: 'medium' },
  { slug: 'gk-india-longest-bridge-dhola', categoryId: 'cat-gk', text: 'The Dhola-Sadiya Bridge, the longest bridge in India over water, is built across which river?', options: ['Brahmaputra (Lohit River)', 'Ganga', 'Godavari', 'Mahanadi'], correctIndex: 0, explanation: 'The Dhola-Sadiya Bridge (Bhupen Hazarika Setu) spans the Lohit River, a tributary of the Brahmaputra, connecting Assam and Arunachal Pradesh. At 9.15 km, it is India\'s longest bridge over water. It was inaugurated in May 2017.', source: 'Ministry of Road Transport and Highways / BRO', difficulty: 'medium' },
  { slug: 'gk-india-first-smart-city', categoryId: 'cat-gk', text: 'India\'s Smart Cities Mission was launched in which year?', options: ['2012', '2015', '2018', '2020'], correctIndex: 1, explanation: 'The Smart Cities Mission was launched on 25 June 2015. It aims to develop 100 cities across India as smart cities with modern infrastructure, sustainable environment, and quality of life. The mission\'s implementation period was initially 5 years (2015-2020) and extended.', source: 'Ministry of Housing and Urban Affairs', difficulty: 'medium' },
  { slug: 'gk-india-census-delay-2021', categoryId: 'cat-gk', text: 'The 2021 Census of India was postponed. What is the next proposed year for the census?', options: ['2024', '2025', '2026', '2027'], correctIndex: 1, explanation: 'The delayed 2021 Census of India is proposed to be conducted in 2025. The previous census was in 2011. The census was postponed due to the COVID-19 pandemic and administrative reasons. It will be the 16th census of India and the first digital census.', source: 'Office of the Registrar General & Census Commissioner / Ministry of Home Affairs', difficulty: 'medium' },
  { slug: 'gk-india-longest-river-bridge-ganga', categoryId: 'cat-gk', text: 'The Mahatma Gandhi Setu, one of the longest river bridges in India, spans the Ganga at which city?', options: ['Varanasi', 'Patna', 'Kolkata', 'Allahabad (Prayagraj)'], correctIndex: 1, explanation: 'The Mahatma Gandhi Setu spans the Ganga at Patna, Bihar. At 5,750 metres (5.75 km), it was India\'s longest river bridge when completed in 1982. It connects Patna in the south to Hajipur in the north. It was built by Gammon India Ltd.', source: 'Ministry of Road Transport and Highways / NHAI', difficulty: 'medium' },
  { slug: 'gk-india-largest-amphitheatre', categoryId: 'cat-gk', text: 'India\'s Republic Day parade is held at which venue in New Delhi?', options: ['India Gate', 'Rajpath (Kartavya Path)', 'Red Fort grounds', 'National Stadium'], correctIndex: 1, explanation: 'The Republic Day parade is held at Kartavya Path (formerly Rajpath), New Delhi. The ceremonial boulevard was renamed from "Rajpath" to "Kartavya Path" (Path of Duty) in September 2022. The parade proceeds from Rashtrapati Bhavan to India Gate.', source: 'Ministry of Defence / New Delhi Municipal Council', difficulty: 'easy' },
  { slug: 'gk-india-metro-first-city', categoryId: 'cat-gk', text: 'Which Indian city was the first to have a metro rail system?', options: ['Delhi', 'Mumbai', 'Kolkata', 'Bengaluru'], correctIndex: 2, explanation: 'Kolkata was the first Indian city to have a metro rail system. The North-South corridor (Esplanade-Bhawanipur, later extended) opened in 1984. The Delhi Metro Rail Corporation (DMRC) was established in 1995, and Delhi Metro began operations in 2002. India now has metro systems in 15+ cities.', source: 'Ministry of Housing and Urban Affairs / Metro Railway, Kolkata', difficulty: 'medium' },
  { slug: 'gk-india-tallest-statue-unity', categoryId: 'cat-gk', text: 'The Statue of Unity, India\'s tallest statue, depicts which person?', options: ['Mahatma Gandhi', 'Sardar Vallabhbhai Patel', 'B.R. Ambedkar', 'Subhas Chandra Bose'], correctIndex: 1, explanation: 'The Statue of Unity (182 m / 597 ft) depicts Sardar Vallabhbhai Patel, India\'s first Deputy Prime Minister. Located at Kevadia, Gujarat, it was unveiled on 31 October 2018. It is the world\'s tallest statue, taller than the Sakyamuni Buddha (153 m) in China and the Spring Temple Buddha (128 m).', source: 'Ministry of Home Affairs / Gujarat Tourism / Sardar Sarovar Narmada Nigam', difficulty: 'easy' },
  { slug: 'gk-india-new-parliament-building', categoryId: 'cat-gk', text: 'The new Parliament building of India was inaugurated in which year?', options: ['2020', '2022', '2023', '2024'], correctIndex: 2, explanation: 'The new Parliament building was inaugurated on 28 May 2023 by Prime Minister Narendra Modi. It is part of the Central Vista Redevelopment Project. The building has a triangular shape, a larger Lok Sabha (888 seats), and Rajya Sabha (384 seats). The old Parliament building (1927) is being repurposed.', source: 'Ministry of Housing and Urban Affairs / Central Public Works Department', difficulty: 'medium' },

  // ═══ cat-history (10) ═══
  { slug: 'hist-indus-valley-brick-ratio', categoryId: 'cat-history', text: 'The standardised bricks of the Indus Valley Civilisation followed what ratio?', options: ['4:2:1', '1:1:1', '3:2:1', '2:1:1'], correctIndex: 0, explanation: 'Indus Valley bricks followed a standardised ratio of 4:2:1 (length:width:height). This standardisation across cities spanning 500,000 sq km demonstrates remarkable administrative coordination. The bricks were typically sun-dried mud or kiln-fired terracotta.', source: 'Archaeological Survey of India', difficulty: 'hard' },
  { slug: 'hist-ashoka-spread-buddhism-children', categoryId: 'cat-history', text: 'Emperor Ashoka sent his son Mahendra and daughter Sanghamitra to which country to spread Buddhism?', options: ['China', 'Sri Lanka', 'Tibet', 'Myanmar (Burma)'], correctIndex: 1, explanation: 'Ashoka sent his son Mahendra (Mahinda) and daughter Sanghamitra to Sri Lanka (Ceylon) to spread Buddhism in the 3rd century BCE. Mahendra brought Buddhism to Sri Lanka and Sanghamitra brought a sapling of the original Bodhi Tree from Bodh Gaya, which still grows in Anuradhapura.', source: 'Indian Council of Historical Research / Mahavamsa (Sri Lankan chronicle)', difficulty: 'medium' },
  { slug: 'hist-gupta-empire-fa-hien', categoryId: 'cat-history', text: 'The Chinese Buddhist monk Fa-Hien (Faxian) visited India during the reign of which Gupta emperor?', options: ['Chandragupta II (Vikramaditya)', 'Samudragupta', 'Kumargupta I', 'Skandagupta'], correctIndex: 0, explanation: 'Fa-Hien visited India during the reign of Chandragupta II (Vikramaditya, r. c. 380-415 CE). He stayed from approximately 405-411 CE, describing the prosperity, governance, and Buddhist institutions of the Gupta Empire. His travelogue provides valuable first-hand accounts of Gupta-era India.', source: 'Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-delhi-sultanate-firoz-shah', categoryId: 'cat-history', text: 'Firoz Shah Tughlaq (r. 1351-1388) is known for which administrative reform?', options: ['Establishing the Mansabdari system', 'Building canals and introducing revenue reforms', 'Introducing the rupee currency', 'Founding the city of Agra'], correctIndex: 1, explanation: 'Firoz Shah Tughlaq is known for building canals (including the 150 km Rajiwah canal) for irrigation and introducing revenue reforms, including the "taswi" system (per-area assessment). He also established hospitals (darul-shifa), sarais (rest houses), and madrasas. He was the cousin and successor of Muhammad bin Tughlaq.', source: 'Indian Council of Historical Research / Tarikh-i-Firoz Shahi', difficulty: 'hard' },
  { slug: 'hist-mughal-babur-origin', categoryId: 'cat-history', text: 'Babur, the founder of the Mughal Empire, was descended from which two famous conquerors?', options: ['Alexander and Darius', 'Genghis Khan and Timur (Tamerlane)', 'Chengiz Khan and Mahmud of Ghazni', 'Tamerlane and Akbar'], correctIndex: 1, explanation: 'Babur was descended from Genghis Khan (through his mother, Kutlugh Nigar Khanum) and Timur (Tamerlane, through his father, Umar Sheikh Mirza). He founded the Mughal Empire after winning the First Battle of Panipat in 1526. The word "Mughal" is derived from "Mongol."', source: 'Indian Council of Historical Research / Baburnama', difficulty: 'medium' },
  { slug: 'hist-bhakti-saint-mirabai-devotion', categoryId: 'cat-history', text: 'The Bhakti saint Mirabai (16th century) was devoted to which deity?', options: ['Lord Rama', 'Lord Krishna', 'Lord Shiva', 'Goddess Durga'], correctIndex: 1, explanation: 'Mirabai (c. 1498-1546) was devoted to Lord Krishna. She was a Rajput princess from Marwar who renounced her royal life to compose devotional bhajans (songs) dedicated to Krishna. She is one of the most famous Bhakti saints, and her compositions are still sung across India today.', source: 'Sahitya Akademi / Indian Council of Historical Research', difficulty: 'easy' },
  { slug: 'hist-1857-rani-lakshmibai-jhansi', categoryId: 'cat-history', text: 'Rani Lakshmibai of Jhansi died fighting the British in 1858 near which city?', options: ['Jhansi', 'Gwalior', 'Kanpur', 'Delhi'], correctIndex: 1, explanation: 'Rani Lakshmibai died on 18 June 1858 while fighting British forces led by Sir Hugh Rose at Gwalior. She had captured Gwalior Fort but was killed during the British counter-attack. She was one of the leading figures of the 1857 revolt, symbolised by her famous quote: "Meri Jhansi nahi doongi" (I will not give up my Jhansi).', source: 'National Archives of India', difficulty: 'medium' },
  { slug: 'hist-indian-national-congress-first', categoryId: 'cat-history', text: 'The Indian National Congress was founded in which year, at which city?', options: ['1883, Bombay', '1885, Bombay', '1885, Calcutta', '1888, Delhi'], correctIndex: 1, explanation: 'The Indian National Congress was founded on 28 December 1885 at Gokuldas Tejpal Sanskrit College, Bombay (Mumbai). It was founded by Allan Octavian Hume, a retired British civil servant. Womesh Chunder Bonnerjee was the first president. The first session was attended by 72 delegates.', source: 'Indian National Congress Archives / National Archives of India', difficulty: 'medium' },
  { slug: 'hist-pakistan-resolution-date', categoryId: 'cat-history', text: 'The "Lahore Resolution" (later called the Pakistan Resolution) was passed by the Muslim League on which date?', options: ['23 March 1940', '16 August 1946', '3 June 1947', '14 August 1947'], correctIndex: 0, explanation: 'The Lahore Resolution was passed on 23 March 1940 at the Muslim League\'s annual session in Lahore, presided by Muhammad Ali Jinnah. It called for the creation of independent states for Muslims in the Muslim-majority regions of India. 23 March is celebrated as Pakistan Day.', source: 'National Archives of India / Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-independence-midnight-speech', categoryId: 'cat-history', text: 'Jawaharlal Nehru delivered his famous "Tryst with Destiny" speech at which time?', options: ['Midnight of 14-15 August 1947', 'Morning of 15 August 1947', 'Evening of 14 August 1947', 'Noon of 15 August 1947'], correctIndex: 0, explanation: 'Nehru delivered the "Tryst with Destiny" speech at the stroke of midnight on 14-15 August 1947, at the Constituent Assembly in New Delhi. The famous opening: "Long years ago we made a tryst with destiny..." India became independent at midnight on 15 August 1947.', source: 'National Archives of India / Parliament of India', difficulty: 'easy' },

  // ═══ cat-geography (10) ═══
  { slug: 'geo-india-longest-river-peninsular-godavari-length', categoryId: 'cat-geography', text: 'The Godavari, the longest river in peninsular India, is approximately how long?', options: ['About 1,000 km', 'About 1,465 km', 'About 2,000 km', 'About 2,525 km'], correctIndex: 1, explanation: 'The Godavari is approximately 1,465 km long, making it the longest river in peninsular India. It originates at Trimbakeshwar in Maharashtra and flows eastward through Telangana, Andhra Pradesh, and into the Bay of Bengal. The Godavari is also called "Dakshin Ganga" (Ganga of the South).', source: 'Ministry of Water Resources / Central Water Commission', difficulty: 'medium' },
  { slug: 'geo-india-highest-peak-outside-himalayas', categoryId: 'cat-geography', text: 'Which is the highest peak in India outside the Himalayan range?', options: ['Doddabetta', 'Anamudi', 'Mahabaleshwar', 'Nilgiri Peak'], correctIndex: 1, explanation: 'Anamudi (2,695 m / 8,842 ft) in Kerala\'s Eravikulam National Park is the highest peak in India outside the Himalayan range. It is located in the Western Ghats (Anaimalai Hills). It is also the highest peak in South India and the Western Ghats.', source: 'Geological Survey of India / Survey of India', difficulty: 'medium' },
  { slug: 'geo-india-land-border-total-length', categoryId: 'cat-geography', text: 'India\'s total land border length is approximately how many kilometres?', options: ['About 10,000 km', 'About 15,200 km', 'About 20,000 km', 'About 25,000 km'], correctIndex: 1, explanation: 'India\'s total land border is approximately 15,200 km. India shares land borders with 7 countries: Pakistan (~3,323 km), China (~3,488 km), Nepal (~1,751 km), Bhutan (~699 km), Bangladesh (~4,096 km), Myanmar (~1,643 km), and Afghanistan (~106 km via Pakistan-occupied Kashmir, disputed).', source: 'Ministry of Home Affairs / Survey of India', difficulty: 'medium' },
  { slug: 'geo-india-area-world-rank', categoryId: 'cat-geography', text: 'India is the seventh-largest country in the world by area. What is its approximate total area?', options: ['About 2.8 million sq km', 'About 3.3 million sq km', 'About 4.0 million sq km', 'About 5.2 million sq km'], correctIndex: 1, explanation: 'India\'s total area is approximately 3.287 million square kilometres (3,287,263 sq km). It is the 7th largest country by area, after Russia, Canada, China, USA, Brazil, and Australia. India accounts for about 2.4% of the world\'s total geographical area.', source: 'Survey of India / Ministry of Home Affairs', difficulty: 'medium' },
  { slug: 'geo-india-state-most-neighbours', categoryId: 'cat-geography', text: 'Which Indian state shares its border with the maximum number of other Indian states?', options: ['Uttar Pradesh', 'Madhya Pradesh', 'Maharashtra', 'Karnataka'], correctIndex: 0, explanation: 'Uttar Pradesh shares borders with the maximum number of Indian states: 9 states (Uttarakhand, Himachal Pradesh, Haryana, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, Bihar) and 1 UT (Delhi). UP is India\'s most populous state and the 4th largest by area.', source: 'Ministry of Home Affairs / Survey of India', difficulty: 'medium' },
  { slug: 'geo-india-deepest-lake', categoryId: 'cat-geography', text: 'Which is the deepest lake in India?', options: ['Wular Lake (J&K)', 'Lonar Lake (Maharashtra)', 'Kolleru Lake (Andhra Pradesh)', 'Vembanad Lake (Kerala)'], correctIndex: 1, explanation: 'Lonar Lake in Maharashtra is the deepest lake in India, formed by a meteorite impact approximately 50,000 years ago. It is approximately 150 m deep and has a diameter of about 1.8 km. The lake water is both alkaline and saline, making it a unique geological feature.', source: 'Geological Survey of India / Ministry of Environment', difficulty: 'hard' },
  { slug: 'geo-india-largest-freshwater-lake', categoryId: 'cat-geography', text: 'Which is the largest freshwater lake in India?', options: ['Wular Lake (J&K)', 'Vembanad Lake (Kerala)', 'Chilika Lake (Odisha)', 'Pulicat Lake (Andhra Pradesh-Tamil Nadu)'], correctIndex: 0, explanation: 'Wular Lake in Jammu & Kashmir is the largest freshwater lake in India. It covers approximately 200 sq km (varies seasonally). It is located between Baramulla and Bandipora districts and is fed by the Jhelum river. Vembanad is the largest lake overall but is brackish (backwater).', source: 'Ministry of Environment, Forest and Climate Change / J&K Tourism', difficulty: 'medium' },
  { slug: 'geo-india-tropic-cancer-states-count', categoryId: 'cat-geography', text: 'The Tropic of Cancer passes through how many Indian states?', options: ['6', '7', '8', '10'], correctIndex: 2, explanation: 'The Tropic of Cancer (23.5°N) passes through 8 Indian states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram. The Tropic of Cancer divides India into a tropical south and a subtropical north.', source: 'Survey of India', difficulty: 'medium' },
  { slug: 'geo-india-monsoon-reversal-winds', categoryId: 'cat-geography', text: 'The Indian monsoon system is characterised by what unique wind pattern?', options: ['Winds blow only from the west', 'Winds reverse direction seasonally (southwest in summer, northeast in winter)', 'Winds blow only from the east', 'Winds are constant year-round'], correctIndex: 1, explanation: 'The Indian monsoon is characterised by seasonal wind reversal: southwest monsoon winds (June-September, bringing heavy rain) and northeast monsoon winds (October-December, retreating/dry for most of India). This reversal is caused by differential heating of land and sea.', source: 'India Meteorological Department (IMD)', difficulty: 'medium' },
  { slug: 'geo-india-easternmost-village', categoryId: 'cat-geography', text: 'Which is the easternmost village in India?', options: ['Kibithu (Arunachal Pradesh)', 'Dong (Arunachal Pradesh)', 'Tezu (Arunachal Pradesh)', 'Pasighat (Arunachal Pradesh)'], correctIndex: 1, explanation: 'Dong village in Arunachal Pradesh, near the Myanmar border, is the easternmost village in India. It is located at approximately 97°E longitude. Dong is known as the place where the sun rises first in India. Kibithu is another easternmost point near the India-China-Myanmar tri-junction.', source: 'Survey of India / Arunachal Pradesh Tourism', difficulty: 'hard' },

  // ═══ cat-civics (10) ═══
  { slug: 'civ-const-schedule-count', categoryId: 'cat-civics', text: 'As of 2024, how many Schedules are there in the Indian Constitution?', options: ['10', '11', '12', '13'], correctIndex: 2, explanation: 'As of 2024, the Indian Constitution has 12 Schedules. The original Constitution had 8 Schedules. The 9th was added by the 1st Amendment (1951), 10th by the 52nd Amendment (1985, Anti-Defection), 11th by the 73rd Amendment (1992, Panchayats), and 12th by the 74th Amendment (1992, Municipalities).', source: 'Constitution of India', difficulty: 'medium' },
  { slug: 'civ-const-parts-count', categoryId: 'cat-civics', text: 'As of 2024, how many Parts are there in the Indian Constitution?', options: ['22', '23', '25', '27'], correctIndex: 2, explanation: 'As of 2024, the Indian Constitution has 25 Parts. The original Constitution had 22 Parts. Part IX (Panchayats) and Part IXA (Municipalities) were added by the 73rd and 74th Amendments (1992). Part IXB (Cooperative Societies) was added by the 97th Amendment (2011), making it 25 Parts total.', source: 'Constitution of India', difficulty: 'medium' },
  { slug: 'civ-president-impeachment-process', categoryId: 'cat-civics', text: 'The process for removing the President of India (impeachment) requires what majority in Parliament?', options: ['Simple majority in both houses', 'Two-thirds majority of the total membership of each house', 'Two-thirds majority of members present and voting in each house', 'Unanimous vote'], correctIndex: 1, explanation: 'Under Article 61, the President can be removed by impeachment for "violation of the Constitution." The process requires a 2/3 majority of the total membership of each house (not just present and voting). The charge must be preferred by one house and investigated by the other. No President has been impeached to date.', source: 'Constitution of India, Article 61', difficulty: 'hard' },
  { slug: 'civ-judicial-activism-pil-india', categoryId: 'cat-civics', text: 'Public Interest Litigation (PIL) in India was pioneered by which Supreme Court judges in the late 1970s-80s?', options: ['Justices P.N. Bhagwati and V.R. Krishna Iyer', 'Justices H.R. Khanna and J.C. Shah', 'Justices R.C. Lahoti and Y.K. Sabharwal', 'Justices S.H. Kapadia and K.G. Balakrishnan'], correctIndex: 0, explanation: 'Public Interest Litigation (PIL) was pioneered by Justices P.N. Bhagwati and V.R. Krishna Iyer in the late 1970s and early 1980s. PIL relaxed the traditional rule of locus standi (standing), allowing public-spirited individuals to file cases on behalf of marginalised groups. This expanded access to justice significantly.', source: 'Supreme Court of India / Constitution of India, Article 32', difficulty: 'hard' },
  { slug: 'civ-const-minority-rights-article-29', categoryId: 'cat-civics', text: 'Article 29 of the Indian Constitution protects which right of minorities?', options: ['Right to establish educational institutions', 'Right to conserve distinct language, script, or culture', 'Right to separate electorates', 'Right to religious conversion'], correctIndex: 1, explanation: 'Article 29 protects the right of any section of citizens with a distinct language, script, or culture to conserve the same. It also prohibits discrimination in admission to state-aided educational institutions on grounds of religion, race, caste, language, or any of them.', source: 'Constitution of India, Article 29', difficulty: 'medium' },
  { slug: 'civ-right-to-privacy-puttaswamy', categoryId: 'cat-civics', text: 'The Supreme Court declared the Right to Privacy as a Fundamental Right in which landmark judgment?', options: ['Kesavananda Bharati v. State of Kerala (1973)', 'Maneka Gandhi v. Union of India (1978)', 'K.S. Puttaswamy v. Union of India (2017)', 'S.R. Bommai v. Union of India (1994)'], correctIndex: 2, explanation: 'In K.S. Puttaswamy v. Union of India (2017), a 9-judge bench unanimously declared the Right to Privacy as a fundamental right under Article 21 (Right to Life and Personal Liberty). This judgment overruled earlier decisions that held privacy was not a fundamental right, and it laid the foundation for data protection laws in India.', source: 'Supreme Court of India, K.S. Puttaswamy v. Union of India (2017)', difficulty: 'medium' },
  { slug: 'civ-collective-responsibility-article-75', categoryId: 'cat-civics', text: 'The principle of collective responsibility of the Council of Ministers is enshrined in which Article?', options: ['Article 73', 'Article 74', 'Article 75(3)', 'Article 78'], correctIndex: 2, explanation: 'Article 75(3) of the Constitution states that the Council of Ministers shall be collectively responsible to the Lok Sabha (House of the People). This means the entire ministry must resign or face a no-confidence vote if the Lok Sabha passes a no-confidence motion against the government.', source: 'Constitution of India, Article 75(3)', difficulty: 'medium' },
  { slug: 'civ-basic-structure-doctrine-kesavananda', categoryId: 'cat-civics', text: 'The "Basic Structure Doctrine" of the Indian Constitution was established by the Supreme Court in which case?', options: ['Golaknath v. State of Punjab (1967)', 'Kesavananda Bharati v. State of Kerala (1973)', 'Minerva Mills v. Union of India (1980)', 'S.R. Bommai v. Union of India (1994)'], correctIndex: 1, explanation: 'The "Basic Structure Doctrine" was established by the Supreme Court in Kesavananda Bharati v. State of Kerala (1973), by a 13-judge bench (7-6 majority). It held that Parliament cannot amend the "basic structure" of the Constitution, even under Article 368. This limits Parliament\'s amending power and protects fundamental features like democracy, secularism, and judicial review.', source: 'Supreme Court of India, Kesavananda Bharati v. State of Kerala (1973)', difficulty: 'medium' },
  { slug: 'civ-president-pardoning-power-article-72', categoryId: 'cat-civics', text: 'Under Article 72, the President of India has the power to grant pardons, reprieves, respites, or remissions for offences against whom?', options: ['Only in cases of state laws', 'Only in cases of Union laws', 'In all cases where the sentence is death or punishment is for an offence under Union law', 'Only in military cases'], correctIndex: 2, explanation: 'Article 72 empowers the President to grant pardons, reprieves, respites, or remissions of punishment, or to suspend, remit, or commute the sentence of any person convicted of an offence: (a) in cases where the punishment or sentence is by a Court-Martial, (b) in all cases where punishment is for an offence under any law relating to Union (central) government jurisdiction, and (c) in all cases involving the death sentence. The Governor has similar power under Article 161 but only for state offences.', source: 'Constitution of India, Article 72', difficulty: 'hard' },
  { slug: 'civ-state-governor-appointment', categoryId: 'cat-civics', text: 'The Governor of a state in India is appointed by whom?', options: ['The President of India', 'The Prime Minister', 'The Chief Minister of the state', 'By direct election'], correctIndex: 0, explanation: 'The Governor is appointed by the President of India (Article 155) and serves at the President\'s pleasure (Article 156). The Governor is the constitutional head of the state executive (Article 154), analogous to the President at the Centre. The Governor\'s role is largely ceremonial but includes important discretionary powers.', source: 'Constitution of India, Articles 154-156', difficulty: 'easy' },

  // ═══ cat-science (10) ═══
  { slug: 'sci-india-atomic-energy-dept-founded', categoryId: 'cat-science', text: 'The Department of Atomic Energy (DAE), Government of India, was established in which year?', options: ['1948', '1954', '1962', '1974'], correctIndex: 1, explanation: 'The Department of Atomic Energy was established on 3 August 1954 under the direct charge of the Prime Minister. It was established under the Atomic Energy Act, 1948, which was revised in 1962. Dr. Homi Bhabha was its first Secretary. The DAE oversees all atomic energy programmes in India, including nuclear power, research, and applications.', source: 'Department of Atomic Energy, Government of India', difficulty: 'medium' },
  { slug: 'sci-india-space-commission-first-chairman', categoryId: 'cat-science', text: 'Who was the first Chairman of the Indian Space Commission (established in 1972)?', options: ['Dr. Vikram Sarabhai', 'Prof. Satish Dhawan', 'Dr. K. Kasturirangan', 'Dr. Homi Bhabha'], correctIndex: 0, explanation: 'Dr. Vikram Sarabhai was the first Chairman of the Indian Space Commission, established in 1972. He is considered the father of the Indian space programme. He founded the Physical Research Laboratory (PRL) in 1947 and was instrumental in establishing ISRO (as INCOSPAR in 1962). After his death in 1971, Prof. Satish Dhawan succeeded him.', source: 'ISRO / Department of Space, Government of India', difficulty: 'medium' },
  { slug: 'sci-india-first-reactor-apsara', categoryId: 'cat-science', text: 'India\'s first nuclear reactor was named "Apsara." In which year was it commissioned?', options: ['1948', '1956', '1962', '1974'], correctIndex: 1, explanation: '"Apsara" was India\'s first nuclear research reactor, commissioned on 4 August 1956 at the Bhabha Atomic Research Centre (BARC), Trombay. It was a swimming pool-type reactor using enriched uranium fuel. Apsara was also Asia\'s first nuclear reactor (outside the USSR). It was decommissioned in 2009 and a new "Apsara-Upgraded" reactor was commissioned in 2018.', source: 'Bhabha Atomic Research Centre (BARC) / Department of Atomic Energy', difficulty: 'medium' },
  { slug: 'sci-india-internet-users-2024', categoryId: 'cat-science', text: 'As of 2024, India has approximately how many internet users (rough estimate)?', options: ['About 300 million', 'About 500 million', 'About 750-800 million', 'About 1.2 billion'], correctIndex: 2, explanation: 'As of 2024, India has approximately 750-800 million internet users (roughly 52-55% of the population). India is the second-largest online market in the world (after China). Jio\'s entry in 2016 accelerated data affordability and adoption. India had about 1.1 billion mobile connections (TRAI, 2023).', source: 'Telecom Regulatory Authority of India (TRAI) / Ministry of Electronics and IT', difficulty: 'medium' },
  { slug: 'sci-india-5g-launch-year', categoryId: 'cat-science', text: '5G mobile services were officially launched in India in which year?', options: ['2020', '2021', '2022', '2023'], correctIndex: 2, explanation: '5G mobile services were officially launched in India on 1 October 2022 at the India Mobile Congress. Airtel and Jio were the first to roll out 5G services. India\'s 5G rollout was among the fastest in the world, with over 400,000 5G base stations installed within about two years. 5G uses the mid-band (3.3-3.6 GHz) and mmWave (26 GHz) spectrum.', source: 'Department of Telecommunications / TRAI', difficulty: 'medium' },
  { slug: 'sci-india-drdo-brahmos-speed', categoryId: 'cat-science', text: 'The BrahMos supersonic cruise missile, jointly developed by India and Russia, travels at approximately what speed?', options: ['Mach 1.0', 'Mach 2.0-2.5', 'Mach 2.8-3.0', 'Mach 5.0'], correctIndex: 2, explanation: 'BrahMos travels at approximately Mach 2.8-3.0 (about 3,400 km/h). It is one of the fastest operational cruise missiles in the world. BrahMos is a joint venture between India\'s DRDO and Russia\'s NPO Mashinostroyenia. The missile can be launched from land, sea, air, and submarine platforms. A hypersonic variant (BrahMos-II) is under development (target: Mach 5-7).', source: 'DRDO / BrahMos Aerospace', difficulty: 'medium' },
  { slug: 'sci-india-covid-genome-sequencing-insacog-labs', categoryId: 'cat-science', text: 'The Indian SARS-CoV-2 Genomics Consortium (INSACOG) was established in December 2020 by the Government of India. How many laboratories did it initially consist of?', options: ['5 labs', '10 labs', '15 labs', '38 labs'], correctIndex: 1, explanation: 'INSACOG was initially established with 10 laboratories in December 2020, expanded to 28 labs by 2021, and later to 38 labs. INSACOG conducts genomic surveillance of SARS-CoV-2 (the virus that causes COVID-19) to track variants. It was set up by the Department of Biotechnology, ICMR, and CSIR.', source: 'Department of Biotechnology / Indian Council of Medical Research (ICMR)', difficulty: 'hard' },
  { slug: 'sci-india-isro-reusable-launch-vehicle', categoryId: 'cat-science', text: 'ISRO\'s RLV (Reusable Launch Vehicle) Technology Demonstration Programme (RLV-TD) successfully tested which capability in 2016 and 2023?', options: ['Moon landing', 'Autonomous runway landing of a winged vehicle', 'Mars orbit insertion', 'Space station docking'], correctIndex: 1, explanation: 'ISRO\'s RLV-TD (Reusable Launch Vehicle - Technology Demonstrator) successfully tested autonomous runway landing of a winged vehicle. The first HEX-01 mission (2016) tested hypersonic flight. The LEX-02 mission (March 2024) demonstrated autonomous landing on a runway. RLV aims to reduce launch costs by enabling reuse of launch vehicles (similar to SpaceX\'s Falcon 9).', source: 'ISRO official website / Department of Space', difficulty: 'hard' },
  { slug: 'sci-india-semiconductor-mission-investment', categoryId: 'cat-science', text: 'India launched the Semiconductor Mission in 2022 with approximately what budget outlay?', options: ['About Rs. 5,000 crore', 'About Rs. 38,000 crore', 'About Rs. 76,000 crore', 'About Rs. 1,00,000 crore'], correctIndex: 2, explanation: 'India launched the India Semiconductor Mission (ISM) in 2022 with an outlay of approximately Rs. 76,000 crore (about $10 billion). It aims to develop India\'s semiconductor and display manufacturing ecosystem. By 2024, several fab proposals were approved, including a Micron Technology facility in Sanand, Gujarat, and Tata Electronics fab in Dholera, Gujarat.', source: 'Ministry of Electronics and IT (MeitY) / India Semiconductor Mission', difficulty: 'medium' },
  { slug: 'sci-india-quantum-computing-mission-2024', categoryId: 'cat-science', text: 'The National Quantum Mission was approved by the Indian government in which year with what budget?', options: ['2020, Rs. 1,000 crore', '2023, Rs. 6,003 crore', '2024, Rs. 10,000 crore', '2022, Rs. 4,000 crore'], correctIndex: 1, explanation: 'The National Quantum Mission was approved in April 2023 with a budget of Rs. 6,003 crore (about $730 million) for 2023-2031. It aims to develop quantum computers with 50-1,000 qubits, quantum communications, and quantum materials. The mission is led by the Department of Science and Technology (DST).', source: 'Department of Science and Technology (DST), Government of India', difficulty: 'hard' },

  // ═══ cat-sports (10) ═══
  { slug: 'spt-india-cricket-world-cup-wins', categoryId: 'cat-sports', text: 'India has won the ICC Cricket World Cup (ODI format) how many times (as of 2024)?', options: ['Once', 'Twice', 'Three times', 'Four times'], correctIndex: 1, explanation: 'India has won the ICC ODI Cricket World Cup twice: in 1983 (under Kapil Dev, defeating West Indies at Lord\'s) and in 2011 (under MS Dhoni, defeating Sri Lanka at Wankhede Stadium, Mumbai). India also won the T20 World Cup in 2007 (under MS Dhoni) and the ICC Champions Trophy in 2013.', source: 'ICC Cricket World Cup records / BCCI', difficulty: 'easy' },
  { slug: 'spt-india-olympic-medals-total-2024', categoryId: 'cat-sports', text: 'As of the Paris 2024 Olympics, India has won a total of how many Olympic medals (individual + team, summer Olympics, all-time)?', options: ['About 20', 'About 35-38', 'About 50', 'About 75'], correctIndex: 1, explanation: 'As of the Paris 2024 Olympics, India has won a total of approximately 38 Olympic medals (summer Olympics): 10 gold, 10 silver, and 18-20 bronze (individual + team). India\'s most successful Olympic sport is hockey (13 medals: 8 gold, 1 silver, 4 bronze). India\'s best individual medal sport is wrestling (7 medals). At Paris 2024, India won 6 medals (1 silver, 5 bronze).', source: 'International Olympic Committee (IOC) / Indian Olympic Association', difficulty: 'medium' },
  { slug: 'spt-india-shooting-world-record-bhaker', categoryId: 'cat-sports', text: 'At the Paris 2024 Olympics, Manu Bhaker became the first Indian to achieve what in a single Olympics?', options: ['Win three gold medals', 'Win two medals in a single Olympics', 'Win an individual gold in shooting', 'Set a world record in shooting'], correctIndex: 1, explanation: 'Manu Bhaker became the first Indian to win two medals at a single Olympics — bronze in the 10m air pistol event and bronze in the 10m air pistol mixed team event (with Sarabjot Singh). She was also the first Indian woman to win an Olympic shooting medal.', source: 'International Olympic Committee (IOC) / National Rifle Association of India', difficulty: 'medium' },
  { slug: 'spt-india-chess-youngest-2700-gukesh', categoryId: 'cat-sports', text: 'Dommaraju Gukesh became the youngest player to achieve what chess milestone (in 2023)?', options: ['Win the World Chess Championship', 'Cross the 2800 FIDE rating mark', 'Defeat Magnus Carlsen in a classical game', 'Win the Candidates Tournament'], correctIndex: 1, explanation: 'Gukesh became the youngest player in history to cross the 2800 FIDE rating mark in 2023 (at age 17). In April 2024, he won the FIDE Candidates Tournament, becoming the youngest-ever challenger for the World Chess Championship. He was born on 29 May 2006 in Chennai.', source: 'World Chess Federation (FIDE)', difficulty: 'medium' },
  { slug: 'spt-india-badminton-thomas-cup-team-members', categoryId: 'cat-sports', text: 'India won its first Thomas Cup (men\'s badminton team championship) in 2022. Which pair won the crucial doubles match in the final?', options: ['Lakshya Sen and Kidambi Srikanth', 'Satwiksairaj Rankireddy and Chirag Shetty', 'Pranav Jerry Chopra and Satwiksairaj Rankireddy', 'HS Prannoy and Kidambi Srikanth'], correctIndex: 1, explanation: 'Satwiksairaj Rankireddy and Chirag Shetty won the crucial doubles match in the Thomas Cup 2022 final, defeating Kevin Sanjaya and Mohammad Ahsan (Indonesia). Lakshya Sen won the first singles, and Kidambi Srikanth won the third match. India defeated Indonesia 3-0 in the final.', source: 'Badminton World Federation (BWF) / Badminton Association of India', difficulty: 'hard' },
  { slug: 'spt-india-athletics-javelin-neeraj-throw-tokyo', categoryId: 'cat-sports', text: 'What was Neeraj Chopra\'s gold medal-winning javelin throw distance at the Tokyo 2020 Olympics (held in 2021)?', options: ['85.58 m', '87.58 m', '89.94 m', '91.50 m'], correctIndex: 1, explanation: 'Neeraj Chopra won Olympic gold with a throw of 87.58 m in the javelin throw final at the Tokyo 2020 Olympics on 7 August 2021. He became the first Indian track-and-field athlete to win Olympic gold. His personal best is 89.94 m (Stockholm Diamond League, June 2022). He also won the 2023 World Athletics Championship gold.', source: 'World Athletics / Athletics Federation of India', difficulty: 'medium' },
  { slug: 'spt-india-para-athletics-avinash-sable', categoryId: 'cat-sports', text: 'Avinash Sable holds the Indian national record in which athletics event?', options: ['Javelin throw', '3000m steeplechase', '400m hurdles', 'Marathon'], correctIndex: 1, explanation: 'Avinash Sable holds the Indian national record in the 3000m steeplechase (8:11.20, set in 2022). He became the first Indian male athlete to qualify for a track final at the World Athletics Championships (2022). He also represented India at the Tokyo 2020 and Paris 2024 Olympics.', source: 'World Athletics / Athletics Federation of India', difficulty: 'hard' },
  { slug: 'spt-india-cricket-highest-chase-test', categoryId: 'cat-sports', text: 'What is India\'s highest successful run chase in Test cricket (4th innings target)?', options: ['406/4 vs West Indies (1976)', '387/4 vs England (2008)', '459 vs Australia (Gabba, 2021)', '445 vs Sri Lanka (2017)'], correctIndex: 1, explanation: 'India\'s highest successful Test chase was 387/4 against England at the MA Chidambaram Stadium, Chennai, in December 2008. Sachin Tendulkar scored 103*, and Yuvraj Singh scored 85*. However, India famously chased down 328 at the Gabba, Brisbane, in January 2021 to win the Border-Gavaskar Trophy against Australia — one of the greatest Test chases by an injury-depleted team.', source: 'ESPN Cricinfo / BCCI / ICC records', difficulty: 'medium' },
  { slug: 'spt-india-boxing-mary-kom-world-champ-years', categoryId: 'cat-sports', text: 'Mary Kom won the World Amateur Boxing Championship gold medals in which years?', options: ['2002, 2005, 2008, 2010', '2002, 2005, 2006, 2008, 2010, 2018', '2005, 2008, 2010, 2014, 2018', '2002, 2006, 2010, 2014, 2018, 2022'], correctIndex: 1, explanation: 'Mary Kom (Chungneijang Mary Kom Hmangte) won the World Amateur Boxing Championship gold medals in 2002, 2005, 2006, 2008, 2010, and 2018 — a record 6 times. She is the only boxer (male or female) to win the World Championship 6 times. She also won an Olympic bronze (2012) and is a Rajya Sabha MP.', source: 'International Boxing Association (IBA) / Boxing Federation of India', difficulty: 'hard' },
  { slug: 'spt-india-hockey-olympic-2024-captain', categoryId: 'cat-sports', text: 'Who captained the Indian men\'s hockey team at the Paris 2024 Olympics, where India won bronze?', options: ['Manpreet Singh', 'Harmanpreet Singh', 'PR Sreejesh', 'Rupinder Pal Singh'], correctIndex: 1, explanation: 'Harmanpreet Singh captained the Indian men\'s hockey team at the Paris 2024 Olympics. India won bronze by defeating Spain 2-1 in the bronze medal match, with Harmanpreet scoring both goals. Goalkeeper PR Sreejesh, playing his final international match, made crucial saves. India won back-to-back Olympic hockey bronzes (Tokyo 2020 and Paris 2024).', source: 'International Hockey Federation (FIH) / Hockey India', difficulty: 'medium' },

  // ═══ cat-culture (10) ═══
  { slug: 'cul-pushkar-camel-fair-state', categoryId: 'cat-culture', text: 'The Pushkar Camel Fair, one of the world\'s largest livestock fairs, is held annually in which Indian state?', options: ['Gujarat', 'Rajasthan', 'Punjab', 'Haryana'], correctIndex: 1, explanation: 'The Pushkar Camel Fair (Pushkar Mela) is held annually in Pushkar, Rajasthan, typically in November during Kartik month. It is one of the world\'s largest livestock fairs, featuring camel trading, cultural events, and religious activities at the Pushkar Lake. The fair attracts about 200,000 visitors annually.', source: 'Department of Tourism, Rajasthan / Ministry of Tourism', difficulty: 'easy' },
  { slug: 'cul-unesco-durga-puja-year', categoryId: 'cat-culture', text: 'Durga Puja in Kolkata was inscribed on the UNESCO Representative List of the Intangible Cultural Heritage of Humanity in which year?', options: ['2018', '2019', '2020', '2021'], correctIndex: 3, explanation: 'Durga Puja in Kolkata was inscribed on UNESCO\'s Representative List of the Intangible Cultural Heritage of Humanity in December 2021 (at the 16th session of the Intergovernmental Committee in Paris). It recognised Durga Puja as a 10-day celebration of the goddess Durga, featuring artistic pandals, idol-making, and cultural performances.', source: 'UNESCO Intangible Cultural Heritage List / Ministry of Culture', difficulty: 'medium' },
  { slug: 'cul-vijayanagara-hampi-unesco-year', categoryId: 'cat-culture', text: 'The ruins of Hampi, the capital of the Vijayanagara Empire, were inscribed as a UNESCO World Heritage Site in which year?', options: ['1983', '1986', '1999', '2003'], correctIndex: 1, explanation: 'The Group of Monuments at Hampi was inscribed as a UNESCO World Heritage Site in 1986. Hampi was the capital of the Vijayanagara Empire (1336-1646 CE) in Karnataka. Key monuments include the Virupaksha Temple, Vittala Temple (with stone chariot), Lotus Mahal, and Elephant Stables. Hampi was added to the List of World Heritage in Danger in 1999 but removed in 2006 after corrective measures.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-kumbh-mela-4-sites', categoryId: 'cat-culture', text: 'The Kumbh Mela is held at four locations. Which of the following is NOT one of them?', options: ['Haridwar', 'Prayagraj (Allahabad)', 'Nashik', 'Bodh Gaya'], correctIndex: 3, explanation: 'The Kumbh Mela is held at four sites: Haridwar (Ganga), Prayagraj/Allahabad (Sangam – Ganga, Yamuna, Saraswati), Nashik (Godavari), and Ujjain (Shipra). Bodh Gaya is not a Kumbh site. The Kumbh Mela at Prayagraj is the largest. The Maha Kumbh is held every 12 years (Prayagraj 2025); Ardh Kumbh every 6 years.', source: 'UNESCO Intangible Cultural Heritage / Ministry of Culture', difficulty: 'medium' },
  { slug: 'cul-classical-dance-kathak-traces', categoryId: 'cat-culture', text: 'The classical dance form Kathak, which originated in North India, traces its roots to which tradition?', options: ['Temple dance of Tamil Nadu', 'Nomadic bards (kathakas) who narrated stories in temples of North India', 'Martial arts of Kerala', 'Court dance of the Chola dynasty'], correctIndex: 1, explanation: 'Kathak traces its roots to the "kathakas" — nomadic bards/storytellers who narrated stories from the epics and Puranas in the temples of North India (Uttar Pradesh, Bihar). The name "Kathak" comes from the Sanskrit word "katha" (story). Kathak later evolved in the courts of Hindu kings and Mughal emperors, incorporating Persian influences.', source: 'Sangeet Natak Akademi / Ministry of Culture', difficulty: 'medium' },
  { slug: 'cul-kuchipudi-origin-andhra', categoryId: 'cat-culture', text: 'Kuchipudi, a classical dance form, originates from which Indian state?', options: ['Tamil Nadu', 'Andhra Pradesh', 'Karnataka', 'Kerala'], correctIndex: 1, explanation: 'Kuchipudi originates from Andhra Pradesh (now Andhra Pradesh and Telangana). It is named after the village of Kuchipudi in Krishna district, Andhra Pradesh. It was traditionally performed by Brahmin men. The Sangeet Natak Akademi recognised Kuchipudi as one of the 8 classical dance forms. It was systematised by Siddhendra Yogi in the 17th century.', source: 'Sangeet Natak Akademi / Andhra Pradesh Tourism', difficulty: 'medium' },
  { slug: 'cul-thanjavur-painting-style', categoryId: 'cat-culture', text: 'Tanjore (Thanjavur) painting, known for its use of gold leaf and semi-precious stones, flourished under which dynasty?', options: ['Pandya dynasty', 'Chola dynasty', 'Maratha dynasty of Thanjavur', 'Vijayanagara Empire'], correctIndex: 2, explanation: 'Tanjore painting (Thanjavur painting) flourished under the Maratha rulers of Thanjavur (17th-19th centuries), though it has roots in the Chola period. The paintings are characterised by rich colours, gold leaf, glass beads, and semi-precious stones on wooden panels. They typically depict Hindu deities and are a GI-tagged product from Tamil Nadu.', source: 'Ministry of Culture / Tamil Nadu Tourism / Geographical Indications Registry', difficulty: 'medium' },
  { slug: 'cul-modi-script-devanagari', categoryId: 'cat-culture', text: 'Which historical script was used for writing Marathi and was the primary court script of the Maratha Empire?', options: ['Devanagari', 'Modi script', 'Brahmi', 'Grantha'], correctIndex: 1, explanation: 'The Modi script was used for writing Marathi and was the primary court script of the Maratha Empire (1674-1818). It is a cursive script derived from Devanagari, designed for faster writing. It was replaced by Devanagari in the mid-20th century. Efforts are ongoing to preserve and digitise Modi script documents.', source: 'Maharashtra State Gazetteer / National Mission for Manuscripts', difficulty: 'hard' },
  { slug: 'cul-vedic-chanting-unesco-india', categoryId: 'cat-culture', text: 'The tradition of Vedic chanting in India was inscribed on UNESCO\'s Intangible Cultural Heritage list in which year?', options: ['2003', '2008', '2010', '2014'], correctIndex: 0, explanation: 'The tradition of Vedic chanting was inscribed on UNESCO\'s Masterpiece of the Oral and Intangible Heritage of Humanity in 2003 (later moved to the Representative List in 2008). Vedic chanting is the oldest unbroken oral tradition in the world, preserving the four Vedas (Rigveda, Yajurveda, Samaveda, Atharvaveda) through memorisation and precise recitation.', source: 'UNESCO Intangible Cultural Heritage / Ministry of Culture', difficulty: 'medium' },
  { slug: 'cul-jaipur-litre-festival-largest', categoryId: 'cat-culture', text: 'Which Indian city hosts the world\'s largest free literary festival, held annually in January?', options: ['Mumbai', 'Jaipur', 'Delhi', 'Kolkata'], correctIndex: 1, explanation: 'The Jaipur Literature Festival (JLF), held annually in January in Jaipur, Rajasthan, is the world\'s largest free literary festival. It was first held in 2006 and attracts over 500,000 attendees annually. The festival features hundreds of authors, poets, and thinkers from around the world.', source: 'Jaipur Literature Festival / Ministry of Culture', difficulty: 'easy' },

  // ═══ cat-economy (10) ═══
  { slug: 'eco-india-gdp-world-ranking-2024', categoryId: 'cat-economy', text: 'As of 2024, India is ranked what in the world by nominal GDP?', options: ['3rd largest economy', '4th largest economy', '5th largest economy', '6th largest economy'], correctIndex: 2, explanation: 'As of 2024, India is the 5th largest economy in the world by nominal GDP (approximately $3.7 trillion). India surpassed the UK in 2022 to become the 5th largest. The IMF projects India to become the 3rd largest economy by 2027, surpassing Japan and Germany.', source: 'International Monetary Fund (IMF) / World Bank', difficulty: 'easy' },
  { slug: 'eco-rbi-inflation-target-4-percent', categoryId: 'cat-economy', text: 'The RBI\'s inflation target (under the flexible inflation targeting framework) is what?', options: ['2% ± 1%', '4% ± 2% (target 4%, tolerance band 2%-6%)', '6% ± 1%', '8% ± 2%'], correctIndex: 1, explanation: 'Under the flexible inflation targeting framework (adopted in 2016), the RBI\'s target is 4% CPI inflation with a tolerance band of ±2% (i.e., 2% to 6%). The Monetary Policy Committee (MPC) sets the policy repo rate to achieve this target. If inflation exceeds 6% or falls below 2% for 3 consecutive quarters, the RBI must report to the government.', source: 'Reserve Bank of India / Monetary Policy Framework Agreement', difficulty: 'medium' },
  { slug: 'eco-india-fdi-policy-retail-2024', categoryId: 'cat-economy', text: 'What is the maximum FDI allowed in multi-brand retail trading in India (as of 2024)?', options: ['26%', '49%', '51%', '100% (with conditions, including minimum $100 million investment and 50% in backend infrastructure)'], correctIndex: 3, explanation: 'India allows 100% FDI in multi-brand retail trading (MBRT), but with stringent conditions, including: minimum $100 million investment, 50% in backend infrastructure, sourcing 30% from MSMEs, and only in cities with population over 1 million (or states may allow smaller cities). Due to these conditions, no major MBRT investment has been approved.', source: 'Department for Promotion of Industry and Internal Trade (DPIIT) / FEMA', difficulty: 'hard' },
  { slug: 'eco-india-gst-number-taxpayers-2024', categoryId: 'cat-economy', text: 'As of 2024, approximately how many taxpayers are registered under GST in India?', options: ['About 50 lakh', 'About 1.4 crore (14 million)', 'About 3 crore (30 million)', 'About 5 crore (50 million)'], correctIndex: 1, explanation: 'As of 2024, approximately 1.4 crore (14 million) taxpayers are registered under GST in India. GST (Goods and Services Tax) was implemented on 1 July 2017, replacing multiple central and state indirect taxes. GST has 5 main rate slabs: 0%, 5%, 12%, 18%, and 28%, plus special rates for gold/diamonds (3%) and luxury/sin goods (40%).', source: 'GST Council / CBIC (Central Board of Indirect Taxes and Customs)', difficulty: 'medium' },
  { slug: 'eco-india-startup-ecosystem-unicorn-2024', categoryId: 'cat-economy', text: 'As of 2024, India has approximately how many "unicorn" startups (privately held companies valued at $1 billion or more)?', options: ['About 30', 'About 50', 'About 100+', 'About 200'], correctIndex: 2, explanation: 'As of 2024, India has approximately 100+ unicorn startups (privately held companies valued at $1 billion+). India has the 3rd largest unicorn ecosystem after the US and China. Notable Indian unicorns include Flipkart, Paytm (before IPO), BYJU\'S, Ola, Zomato (before IPO), Swiggy, Razorpay, and PhonePe. Bengaluru, Delhi NCR, and Mumbai are the top startup hubs.', source: 'NASSCOM / Ministry of Commerce and Industry / Startup India', difficulty: 'medium' },
  { slug: 'eco-india-exports-2024-approximate', categoryId: 'cat-economy', text: 'India\'s total exports (goods + services) in FY 2023-24 were approximately how much?', options: ['About $200 billion', 'About $400 billion', 'About $778 billion', 'About $1,000 billion'], correctIndex: 2, explanation: 'India\'s total exports (goods + services) in FY 2023-24 were approximately $778 billion, with merchandise exports of about $437 billion and services exports of about $341 billion. India\'s top export destinations include the US, UAE, China, Bangladesh, and Singapore. Top exports include petroleum products, gems & jewellery, pharmaceuticals, engineering goods, and IT services.', source: 'Ministry of Commerce and Industry / Directorate General of Commercial Intelligence and Statistics', difficulty: 'medium' },
  { slug: 'eco-india-jandhan-accounts-2024', categoryId: 'cat-economy', text: 'How many Jan Dhan bank accounts had been opened by approximately 2024 since the scheme\'s launch in 2014?', options: ['About 100 million', 'About 300 million', 'About 500 million', 'About 750 million'], correctIndex: 2, explanation: 'Approximately 500 million (50 crore) Jan Dhan accounts had been opened by 2024, with total deposits exceeding Rs. 2 lakh crore. PMJDY was launched on 28 August 2014. It is one of the world\'s largest financial inclusion programmes, providing zero-balance bank accounts with debit cards, accident insurance, and overdraft facilities.', source: 'Ministry of Finance / Department of Financial Services', difficulty: 'medium' },
  { slug: 'eco-india-agriculture-gdp-share', categoryId: 'cat-economy', text: 'The agriculture sector contributes approximately what percentage to India\'s GDP (as of 2023-24)?', options: ['About 5%', 'About 15-18%', 'About 30%', 'About 50%'], correctIndex: 1, explanation: 'The agriculture and allied sectors contribute approximately 15-18% to India\'s GDP (as of 2023-24), down from about 50% at independence. However, agriculture still employs approximately 42-46% of India\'s workforce. India is the world\'s largest producer of milk, pulses, and jute, and the 2nd largest producer of rice, wheat, and sugar.', source: 'Ministry of Agriculture and Farmers Welfare / Economic Survey of India', difficulty: 'medium' },
  { slug: 'eco-india-services-sector-gdp', categoryId: 'cat-economy', text: 'The services sector contributes approximately what percentage to India\'s GDP (as of 2023-24)?', options: ['About 25%', 'About 40%', 'About 53-55%', 'About 70%'], correctIndex: 2, explanation: 'The services sector contributes approximately 53-55% to India\'s GDP (as of 2023-24), making it the largest sector of the Indian economy. Key services include IT/ITeS, finance, telecommunications, tourism, and healthcare. The services sector accounts for about 30% of total employment but contributes over 50% of India\'s exports.', source: 'Ministry of Finance / Economic Survey of India / NITI Aayog', difficulty: 'medium' },
  { slug: 'eco-india-upi-2024-transactions-value', categoryId: 'cat-economy', text: 'UPI (Unified Payments Interface) transactions in India in 2023-24 were approximately what in value?', options: ['About Rs. 50 lakh crore', 'About Rs. 100 lakh crore', 'About Rs. 199 lakh crore', 'About Rs. 500 lakh crore'], correctIndex: 2, explanation: 'In FY 2023-24, UPI transactions totalled approximately Rs. 199 lakh crore (about $2.4 trillion) in value across about 131 billion transactions. India accounts for approximately 46% of all real-time digital payment transactions worldwide. UPI was launched in April 2016 by NPCI.', source: 'National Payments Corporation of India (NPCI) / RBI', difficulty: 'medium' },

  // ═══ cat-environment (10) ═══
  { slug: 'env-india-mangrove-cover-area', categoryId: 'cat-environment', text: 'According to the India State of Forest Report 2021, what is India\'s approximate mangrove cover?', options: ['About 2,500 sq km', 'About 4,992 sq km', 'About 7,500 sq km', 'About 10,000 sq km'], correctIndex: 1, explanation: 'According to the India State of Forest Report 2021 (Forest Survey of India), India\'s mangrove cover is approximately 4,992 sq km, an increase of 17 sq km from the 2019 assessment. The largest mangrove cover is in West Bengal (Sundarbans, 2,114 sq km), followed by Gujarat (1,222 sq km) and Andaman & Nicobar (616 sq km).', source: 'Forest Survey of India, Ministry of Environment', difficulty: 'medium' },
  { slug: 'env-india-wild-assam-rhino-population', categoryId: 'cat-environment', text: 'According to the 2022 rhino census at Kaziranga National Park, approximately how many one-horned rhinos live there?', options: ['About 1,500', 'About 2,613', 'About 3,500', 'About 4,000'], correctIndex: 1, explanation: 'The 2022 rhino census at Kaziranga National Park, Assam, counted 2,613 one-horned rhinos (Indian rhinos). Kaziranga hosts about 70% of the world\'s one-horned rhino population. The total Indian rhino population is about 4,000, including populations at Pobitora (102), Orang (125), and Dudhwa (40+).', source: 'Ministry of Environment, Forest and Climate Change / Assam Forest Department', difficulty: 'medium' },
  { slug: 'env-india-national-parks-count-2024', categoryId: 'cat-environment', text: 'As of 2024, India has approximately how many National Parks?', options: ['About 55', 'About 75', 'About 106', 'About 150'], correctIndex: 2, explanation: 'As of 2024, India has approximately 106 National Parks (plus 567 Wildlife Sanctuaries and 55 Tiger Reserves). The first national park in India was Jim Corbett National Park (established in 1936 as Hailey National Park, renamed in 1957). The total Protected Area coverage is approximately 5% of India\'s geographical area.', source: 'Ministry of Environment, Forest and Climate Change / National Wildlife Database', difficulty: 'medium' },
  { slug: 'env-india-solar-capacity-2024', categoryId: 'cat-environment', text: 'As of 2024, India\'s installed solar power capacity is approximately how many gigawatts (GW)?', options: ['About 25 GW', 'About 50 GW', 'About 73-75 GW', 'About 100 GW'], correctIndex: 2, explanation: 'As of mid-2024, India\'s installed solar power capacity is approximately 73-75 GW. India had set a target of 100 GW of solar capacity by 2022 (later revised to 2026-27). India is the 5th largest solar power producer in the world. The Bhadla Solar Park in Rajasthan (2,245 MW) is one of the world\'s largest solar parks.', source: 'Ministry of New and Renewable Energy (MNRE) / Central Electricity Authority', difficulty: 'medium' },
  { slug: 'env-india-cop28-green-credits', categoryId: 'cat-environment', text: 'At COP28 (2023), India launched the "Green Credit Initiative" to do what?', options: ['Carbon credit trading', 'Create a market-based mechanism to incentivise environmental actions (tree plantation, water conservation, etc.)', 'Subsidise electric vehicles', 'Build solar power plants'], correctIndex: 1, explanation: 'The "Green Credit Initiative" (GCP), launched at COP28 (December 2023), creates a market-based mechanism to incentivise environmental actions like tree plantation, water conservation, waste management, and sustainable agriculture. Participants earn "Green Credits" for their actions, which can be traded. The Ministry of Environment administers the GCP.', source: 'Ministry of Environment, Forest and Climate Change / UNFCCC COP28', difficulty: 'hard' },
  { slug: 'env-india-ramsar-2016-2024', categoryId: 'cat-environment', text: 'India has added the most Ramsar Sites between which years (the largest addition)?', options: ['2010-2015', '2016-2020', '2021-2024', '2005-2010'], correctIndex: 2, explanation: 'India added the most Ramsar Sites between 2021-2024, growing from about 42 to 75+ sites. In 2022 alone, India added 10 new Ramsar Sites. As of early 2024, India has approximately 75+ Ramsar Sites covering about 1.33 million hectares — the largest network in South Asia.', source: 'Ministry of Environment, Forest and Climate Change / Ramsar Convention Secretariat', difficulty: 'medium' },
  { slug: 'env-india-tiger-census-method', categoryId: 'cat-environment', text: 'India\'s tiger census uses which primary method for estimating tiger populations?', options: ['Aerial survey only', 'Camera trapping (individual identification from stripe patterns) and DNA analysis', 'Pugmark tracking only', 'Radio telemetry only'], correctIndex: 1, explanation: 'India\'s tiger census primarily uses camera trapping (identifying individual tigers from their unique stripe patterns) and DNA analysis of scat samples. This method, used since 2006, replaced the earlier pugmark census method. The 2022 census estimated 3,167 tigers. India hosts about 75% of the world\'s wild tigers.', source: 'National Tiger Conservation Authority (NTCA) / Wildlife Institute of India', difficulty: 'medium' },
  { slug: 'env-india-forest-survey-organization', categoryId: 'cat-environment', text: 'The Forest Survey of India (FSI) is an organisation under which ministry?', options: ['Ministry of Agriculture', 'Ministry of Environment, Forest and Climate Change', 'Ministry of Rural Development', 'Ministry of Science and Technology'], correctIndex: 1, explanation: 'The Forest Survey of India (FSI) is an organisation under the Ministry of Environment, Forest and Climate Change, headquartered in Dehradun. FSI is responsible for assessing and monitoring India\'s forest cover through satellite remote sensing and field surveys. It publishes the biennial "India State of Forest Report."', source: 'Forest Survey of India / Ministry of Environment, Forest and Climate Change', difficulty: 'easy' },
  { slug: 'env-india-cleantech-wind-capacity', categoryId: 'cat-environment', text: 'As of 2024, India\'s installed wind power capacity is approximately how many gigawatts (GW)?', options: ['About 20 GW', 'About 45 GW', 'About 75 GW', 'About 100 GW'], correctIndex: 1, explanation: 'As of 2024, India\'s installed wind power capacity is approximately 45 GW. India has the 4th largest wind power capacity in the world (after China, USA, and Germany). Tamil Nadu has the largest wind capacity among Indian states. India has set a target of 140 GW of wind power capacity by 2030.', source: 'Ministry of New and Renewable Energy (MNRE) / Central Electricity Authority', difficulty: 'medium' },
  { slug: 'env-india-plastic-waste-generation', categoryId: 'cat-environment', text: 'India generates approximately how many million tonnes of plastic waste annually (as of 2023-24)?', options: ['About 1 million tonnes', 'About 3.5 million tonnes', 'About 10 million tonnes', 'About 25 million tonnes'], correctIndex: 1, explanation: 'India generates approximately 3.5 million tonnes of plastic waste annually (as of 2023-24 estimates by CPCB). Only about 60% of this is recycled. The remaining ends up in landfills, drains, and oceans. India banned 19 single-use plastic items from 1 July 2022. The Plastic Waste Management Rules, 2016 (amended in 2022) govern plastic waste management in India.', source: 'Central Pollution Control Board (CPCB) / Ministry of Environment', difficulty: 'medium' },

  // ═══ cat-art (10) ═══
  { slug: 'art-rabindranath-tagore-nobel-1913', categoryId: 'cat-art', text: 'Rabindranath Tagore received the Nobel Prize in Literature in 1913 primarily for which work?', options: ['The Post Office', 'Gitanjali (Song Offerings)', 'Gora', 'The Home and the World'], correctIndex: 1, explanation: 'Tagore received the Nobel Prize in Literature in 1913 for "Gitanjali" (Song Offerings), a collection of 157 devotional poems. Tagore translated the Bengali poems into English himself. He was the first Asian and non-European Nobel laureate. The Nobel citation praised the poems\' "consummate skill, perfect form, and profound spiritual insight."', source: 'Nobel Prize Foundation', difficulty: 'easy' },
  { slug: 'art-hindustani-classical-tansen-akbar', categoryId: 'cat-art', text: 'Tansen, one of India\'s greatest musicians, was one of the "Navaratnas" (Nine Gems) in whose court?', options: ['Emperor Akbar', 'Emperor Shah Jahan', 'Maharana Pratap', 'Krishnadevaraya'], correctIndex: 0, explanation: 'Tansen (c. 1500-1589) was one of the "Navaratnas" (Nine Gems) in Emperor Akbar\'s court. Originally named Ramtanu Pandey, he was born in Gwalior. He was a master of the Dhrupad style and is credited with creating several ragas (including Miyan ki Todi and Miyan ki Malhar). His tomb is in Gwalior.', source: 'Sangeet Natak Akademi / Ministry of Culture', difficulty: 'medium' },
  { slug: 'art-bharatanatyam-devadasi-origin', categoryId: 'cat-art', text: 'Bharatanatyam was originally performed by which community of temple dancers?', options: ['Nattuvanars', 'Devadasis (women dedicated to temple deities)', 'Guru-shishya lineage of Brahmin men', 'Kathak dancers'], correctIndex: 1, explanation: 'Bharatanatyam was originally performed by Devadasis — women dedicated to temple deities in Tamil Nadu. The Devadasi system was abolished in the early 20th century. Rukmini Devi Arundale revived and codified Bharatanatyam in the 1930s, founding Kalakshetra in 1936. She removed the dance from its original temple/Devadasi context and made it a respectable art form accessible to all.', source: 'Sangeet Natak Akademi / Kalakshetra Foundation', difficulty: 'medium' },
  { slug: 'art-indian-miniature-painting-origin', categoryId: 'cat-art', text: 'The Western Indian style of miniature painting, one of the earliest Indian miniature traditions, was primarily used to illustrate which type of texts?', options: ['Mughal chronicles', 'Jain manuscripts (Kalpasutra, etc.)', 'Hindu Puranas', 'Sikh religious texts'], correctIndex: 1, explanation: 'The Western Indian style of miniature painting (c. 12th-16th century) was primarily used to illustrate Jain manuscripts, particularly the Kalpasutra (Book of Rituals). These paintings, from Gujarat and Rajasthan, featured stylised figures with prominent eyes and angular bodies. They were executed on palm leaf and later paper.', source: 'National Museum, New Delhi / Archaeological Survey of India', difficulty: 'hard' },
  { slug: 'art-ravi-varma-oil-painting', categoryId: 'cat-art', text: 'Raja Ravi Varma (1848-1906) is known for pioneering which style of painting in India?', options: ['Mughal miniature', 'European academic oil painting style with Indian mythological themes', 'Abstract painting', 'Bengal School of Art'], correctIndex: 1, explanation: 'Raja Ravi Varma pioneered the fusion of European academic oil painting techniques with Indian mythological themes. He is famous for his depictions of scenes from the Ramayana, Mahabharata, and Puranas. He also established a oleography press to mass-produce his paintings, making art accessible to the common people. He was from the Kilimanoor royal family of Travancore (Kerala).', source: 'National Gallery of Modern Art / Ministry of Culture', difficulty: 'medium' },
  { slug: 'art-mahabharata-bhagavad-gita-chapter', categoryId: 'cat-art', text: 'The Bhagavad Gita, the sacred Hindu text, is part of which book (Parva) of the Mahabharata?', options: ['Adi Parva', 'Bhishma Parva', 'Udyoga Parva', 'Drona Parva'], correctIndex: 1, explanation: 'The Bhagavad Gita is part of the Bhishma Parva (Book of Bhishma), the 6th book of the Mahabharata. It contains 18 chapters (chapters 25-42 of Bhishma Parva) and 700 verses. The Gita is a dialogue between Krishna and Arjuna on the battlefield of Kurukshetra, just before the great war begins. It is one of the most important texts of Hindu philosophy.', source: 'Sahitya Akademi / Encyclopaedia Britannica', difficulty: 'medium' },
  { slug: 'art-panini-ashtadhyayi-sutras', categoryId: 'cat-art', text: 'Panini\'s "Ashtadhyayi" is structured into how many chapters (adhyayas)?', options: ['4', '6', '8', '12'], correctIndex: 2, explanation: 'Panini\'s "Ashtadhyayi" (Eight Chapters) is structured into 8 chapters (adhyayas), each containing 4 sections (padas). It contains approximately 3,959 sutras (rules) that define Sanskrit grammar. It is one of the most sophisticated grammatical treatises ever produced, incorporating concepts like formal language theory that predate modern linguistics by millennia.', source: 'Indian National Science Academy / Encyclopaedia Britannica', difficulty: 'medium' },
  { slug: 'art-kerala-kathakali-makeup-types', categoryId: 'cat-art', text: 'In Kathakali, the elaborate makeup system classifies characters into how many main types based on their moral nature?', options: ['3 types', '5 types (Pacha, Kathi, Kari, Thadi, Minukku)', '8 types', '12 types'], correctIndex: 1, explanation: 'Kathakali classifies characters into 5 main makeup types based on moral nature: Pacha (green, noble/heroic), Kathi (knife, villainous but noble), Kari (black, demoness), Thadi (beard, further sub-divided into Chuvanna/Red, Vella/White, Karutta/Black for different character types), and Minukku (radiant, for female and gentle male characters). The makeup takes hours to apply.', source: 'Sangeet Natak Akademi / Kerala Kalamandalam', difficulty: 'hard' },
  { slug: 'art-madhubani-bharni-katchni', categoryId: 'cat-art', text: 'Madhubani painting has five distinct styles. Which style is characterised by only black and white colours?', options: ['Bharni', 'Katchni', 'Godna', 'Tantrik'], correctIndex: 1, explanation: 'Katchni (Kachni) is the Madhubani style characterised by only black and white colours (fine line work). The other styles are: Bharni (filled with bright colours), Godna (tattoo-like, originally by lower-caste artists), Tantrik (depicting tantric symbols), and Kohbar (wedding chamber paintings). Madhubani art originated in Bihar\'s Mithila region.', source: 'Ministry of Culture / Bihar Tourism / National Handicrafts Development Corporation', difficulty: 'hard' },
  { slug: 'art-indian-cinema-satyajit-ray-pather', categoryId: 'cat-art', text: 'Satyajit Ray\'s debut film "Pather Panchali" (Song of the Little Road) was released in which year?', options: ['1950', '1955', '1960', '1965'], correctIndex: 1, explanation: '"Pather Panchali" was released on 26 August 1955. It was the first film of the "Apu Trilogy" (followed by "Aparajito" 1956 and "Apur Sansar" 1959). It won the Best Human Document award at the 1956 Cannes Film Festival. The film is based on Bibhutibhushan Bandyopadhyay\'s 1929 Bengali novel of the same name. Ray received an Honorary Academy Award in 1992.', source: 'National Film Archive of India / Academy of Motion Picture Arts and Sciences', difficulty: 'medium' },

  // ═══ cat-edu (10) ═══
  { slug: 'edu-mid-day-meal-scheme-origin', categoryId: 'cat-edu', text: 'The Mid-Day Meal Scheme in India, which provides free lunches to school children, was launched as a centrally sponsored scheme in which year?', options: ['1985', '1995', '2001', '2010'], correctIndex: 1, explanation: 'The Mid-Day Meal Scheme was launched as a centrally sponsored scheme on 15 August 1995. It was initially called the "National Programme of Nutritional Support to Primary Education." In 2001, the Supreme Court ordered all states to provide cooked mid-day meals in all government and government-aided primary schools. The scheme covers Classes 1-8 and is now called PM POSHAN (2021).', source: 'Ministry of Education / PM POSHAN scheme', difficulty: 'medium' },
  { slug: 'edu-beti-bachao-beti-padhao-year', categoryId: 'cat-edu', text: 'The "Beti Bachao Beti Padhao" (Save the Girl Child, Educate the Girl Child) scheme was launched in which year?', options: ['2012', '2015', '2018', '2020'], correctIndex: 1, explanation: '"Beti Bachao Beti Padhao" was launched on 22 January 2015 in Panipat, Haryana. It aims to address the declining child sex ratio and promote the education and empowerment of the girl child. The scheme is jointly administered by the Ministry of Women and Child Development, Ministry of Health and Family Welfare, and Ministry of Education.', source: 'Ministry of Women and Child Development / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-skill-india-pmkvy-3-2020', categoryId: 'cat-edu', text: 'PMKVY (Pradhan Mantri Kaushal Vikas Yojana) 3.0 was launched in which year?', options: ['2018', '2020', '2022', '2024'], correctIndex: 1, explanation: 'PMKVY 3.0 was launched in 2021 (announced in Budget 2020). PMKVY is the flagship skill development scheme of the Ministry of Skill Development and Entrepreneurship, implemented by the National Skill Development Corporation (NSDC). PMKVY 1.0 launched in 2015, PMKVY 2.0 in 2016-2020, PMKVY 3.0 in 2021-2026. The scheme trains youth in industry-relevant skills and provides certification.', source: 'Ministry of Skill Development and Entrepreneurship / NSDC', difficulty: 'medium' },
  { slug: 'edu-ugc-net-conducting-body-change', categoryId: 'cat-edu', text: 'The UGC-NET (National Eligibility Test) for determining eligibility for Assistant Professor and JRF was being conducted by which body since December 2018?', options: ['CBSE', 'University Grants Commission (UGC)', 'National Testing Agency (NTA)', 'NTA (with UGC notification from June 2024 that NET will be conducted by UGC again)'], correctIndex: 2, explanation: 'The NTA conducted UGC-NET since December 2018. However, after alleged irregularities in the June 2024 UGC-NET exam, the government cancelled it and transferred NET conduct back to the UGC from June 2024. The NTA was established in 2017. The UGC-NET determines eligibility for Assistant Professor and Junior Research Fellowship (JRF) in Indian universities and colleges.', source: 'National Testing Agency (NTA) / UGC / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-iits-special-tag-institute', categoryId: 'cat-edu', text: 'Under the Institutes of Technology Act, 1961 (amended in 2017/2018), IITs are declared as what?', options: ['Private institutions', 'Deemed universities', 'Institutions of National Importance', 'Central universities'], correctIndex: 2, explanation: 'Under the Institutes of Technology Act, 1961 (as amended), IITs are declared "Institutions of National Importance." This gives them autonomy in academic, administrative, and financial matters. The IIM Act, 2017 granted similar status to IIMs. There are 23 IITs and 20 IIMs (as of 2024). The IITs are governed by the IIT Council, chaired by the Minister of Education.', source: 'Ministry of Education / IIT Council / Institutes of Technology Act', difficulty: 'medium' },
  { slug: 'edu-unesco-learning-city-berhampur', categoryId: 'cat-edu', text: 'In 2023, which Indian city (in addition to Bengaluru) was added to the UNESCO Global Network of Learning Cities?', options: ['Mumbai', 'Berhampur (Odisha)', 'Chennai', 'Pune'], correctIndex: 1, explanation: 'In 2023, Berhampur (Brahmapur) in Odisha was added to the UNESCO Global Network of Learning Cities (GNLC), becoming India\'s second city after Bengaluru (2023). The UNESCO Learning City designation recognises cities that promote lifelong learning through inclusive educational policies and programmes.', source: 'UNESCO Institute for Lifelong Learning', difficulty: 'hard' },
  { slug: 'edu-swachh-bharat-school-toilets', categoryId: 'cat-edu', text: 'The Swachh Bharat Mission (Clean India Mission) included a component for construction of school toilets. Approximately how many school toilets were built between 2014-2019?', options: ['About 50,000', 'About 100,000', 'About 400,000-500,000', 'About 1 million'], correctIndex: 2, explanation: 'Approximately 400,000-500,000 school toilets were built between 2014-2019 under the Swachh Bharat Mission-Swachh Vidyalaya initiative. The programme aimed to provide separate toilets for girls and boys in every school. The SSA (Sarva Shiksha Abhiyan) and RMSA (Rashtriya Madhyamik Shiksha Abhiyan) also contributed.', source: 'Ministry of Education / Ministry of Housing and Urban Affairs', difficulty: 'hard' },
  { slug: 'edu-stem-girls-vigyan-jyoti', categoryId: 'cat-edu', text: 'The "Vigyan Jyoti" scheme, aimed at encouraging girls to pursue STEM education, was launched by which department?', options: ['Ministry of Education', 'Department of Science and Technology (DST)', 'NCERT', 'Ministry of Women and Child Development'], correctIndex: 1, explanation: '"Vigyan Jyoti" was launched by the Department of Science and Technology (DST) in 2019-20. It aims to encourage meritorious girl students from Class 9 to 12 to pursue STEM (Science, Technology, Engineering, and Mathematics) fields in higher education. The programme includes mentoring, campus visits, science camps, and interactions with women scientists.', source: 'Department of Science and Technology (DST) / Ministry of Science and Technology', difficulty: 'hard' },
  { slug: 'edu-national-curriculum-framework-2023', categoryId: 'cat-edu', text: 'The National Curriculum Framework (NCF) for School Education was revised and released in which year (aligned with NEP 2020)?', options: ['2020', '2022', '2023', '2024'], correctIndex: 2, explanation: 'The National Curriculum Framework (NCF) for School Education was released in 2023, aligned with NEP 2020. It introduces a new 5+3+3+4 structure (Foundational, Preparatory, Middle, Secondary). Key changes include: two board exams per year (Class 10 & 12), elimination of hard subject stream separation, multilingual education, and focus on experiential learning. The NCF was developed by NCERT.', source: 'Ministry of Education / NCERT / National Curriculum Framework 2023', difficulty: 'medium' },
  { slug: 'edu-student-startup-policy-national', categoryId: 'cat-edu', text: 'The "National Innovation and Start-up Policy" for students and faculty was launched by which ministry in 2019?', options: ['Ministry of Education (AICTE)', 'Ministry of Commerce and Industry', 'Ministry of Skill Development', 'NITI Aayog'], correctIndex: 0, explanation: 'The "National Innovation and Start-up Policy" (NISP) was launched in 2019 by the Ministry of Education (through AICTE). It aims to create a startup ecosystem in higher educational institutions. The policy encourages students and faculty to start ventures, provides IP rights guidelines, allows faculty to take sabbaticals for startups, and enables student entrepreneurs to take a gap year.', source: 'AICTE / Ministry of Education', difficulty: 'hard' },
];

async function main() {
  console.log('=== Batch 6 Import ===\n');
  const existing = await db.quizQuestion.findMany({ select: { id: true, text: true } });
  const existingTexts = existing.map((q) => q.text);
  const existingSlugs = new Set(existing.map((q) => q.id));
  console.log(`Existing: ${existing.length}, Batch: ${BATCH.length}\n`);

  let imported = 0, skipped = 0, rejected = 0, warned = 0;
  const rejections: Array<{ slug: string; errors: string[] }> = [];
  const warningsLog: Array<{ slug: string; warnings: string[] }> = [];

  for (const q of BATCH) {
    if (existingSlugs.has(q.slug)) { skipped++; continue; }
    const errors: string[] = [];
    const warnings: string[] = [];

    if (!q.text || q.text.trim().length < 10) errors.push('text too short');
    if (q.options.length !== 4) errors.push(`expected 4 options, got ${q.options.length}`);
    if (q.correctIndex < 0 || q.correctIndex >= 4) errors.push('invalid correctIndex');
    if (!q.explanation || q.explanation.trim().length < 10) errors.push('explanation too short');
    if (!q.source || q.source.trim().length < 3) errors.push('source required');
    if (!['easy','medium','hard'].includes(q.difficulty)) errors.push('invalid difficulty');

    const dupResult = checkDuplicate(q.text, existingTexts);
    if (dupResult.isExactDuplicate) errors.push(`exact duplicate: ${dupResult.reason}`);
    else if (dupResult.isNearDuplicate) warnings.push(`near-duplicate: ${dupResult.reason}`);

    if (errors.length > 0) { rejected++; rejections.push({ slug: q.slug, errors }); continue; }
    if (warnings.length > 0) { warned++; warningsLog.push({ slug: q.slug, warnings }); }

    const options = q.options.map((text, i) => ({ id: String.fromCharCode(97 + i), text }));
    try {
      await db.quizQuestion.create({
        data: {
          id: q.slug, categoryId: q.categoryId, text: q.text.trim(), translations: '{}',
          options: JSON.stringify(options), correctOptionIndex: q.correctIndex,
          explanation: q.explanation.trim(), explanationTranslations: '{}',
          source: q.source.trim(), difficulty: q.difficulty, language: 'en', published: true,
        },
      });
      existingTexts.push(q.text);
      imported++;
    } catch (e) {
      rejected++;
      rejections.push({ slug: q.slug, errors: [(e as Error).message] });
    }
  }

  console.log(`\n=== Import Summary ===`);
  console.log(`  Imported: ${imported}`);
  console.log(`  Skipped: ${skipped}`);
  console.log(`  Rejected: ${rejected}`);
  console.log(`  Warnings: ${warned}`);
  if (rejections.length > 0) {
    console.log(`\n  --- Rejected ---`);
    for (const r of rejections) console.log(`  [${r.slug}] ${r.errors.join('; ')}`);
  }
  if (warningsLog.length > 0) {
    console.log(`\n  --- Near-duplicate warnings ---`);
    for (const w of warningsLog) console.log(`  [${w.slug}] ${w.warnings.join('; ')}`);
  }

  console.log(`\n=== Post-import counts ===`);
  const allCats = ['cat-gk','cat-history','cat-geography','cat-civics','cat-science','cat-sports','cat-culture','cat-economy','cat-environment','cat-art','cat-edu'];
  let total = 0;
  for (const cat of allCats) {
    const c = await db.quizQuestion.count({ where: { categoryId: cat } });
    if (c > 0) console.log(`  ${cat}: ${c}`);
    total += c;
  }
  console.log(`  TOTAL: ${total}`);
}

main().then(() => process.exit(0));
